INSERT INTO Language_en_US (Tag, Text) VALUES
('TXT_KEY_TRAIT_UNA_COURT_LIVES_THROUGH_HIM', 'The Court Lives Through Him'),
('TXT_KEY_TRAIT_UNA_COURT_LIVES_THROUGH_HIM_SHORT', 'The Court Lives Through Him'),
('TXT_KEY_TRAIT_UNA_COURT_LIVES_THROUGH_HIM_HELP', 'While Trentrouls lives, all cities gain +1% [ICON_FOOD] Food, [ICON_PRODUCTION] Production, [ICON_GOLD] Gold, [ICON_RESEARCH] Science, [ICON_CULTURE] Culture, [ICON_PEACE] Faith, and Great Person generation for each Era reached. These bonuses are doubled while Buddy is adjacent to Trentrouls. If Trentrouls dies, Una Court collapses.'),

('TXT_KEY_LEADER_UNA_TRENTROULS', 'Trentrouls'),
('TXT_KEY_LEADER_UNA_TRENTROULS_PEDIA', 'Trentrouls is the irreplaceable ruler of Una Court. Its prosperity, military confidence, and continued existence are inseparable from his survival. With Buddy at his side he is formidable; without that companionship, every march toward the front is an intolerable risk.'),
('TXT_KEY_CIVILOPEDIA_LEADERS_UNA_TRENTROULS', 'Trentrouls'),

('TXT_KEY_CIV_UNA_COURT_DESC', 'The Freehold of Una Court'),
('TXT_KEY_CIV_UNA_COURT_SHORT_DESC', 'Una Court'),
('TXT_KEY_CIV_UNA_COURT_ADJECTIVE', 'Una Court'),
('TXT_KEY_CIV_UNA_COURT_PEDIA', 'The Freehold of Una Court is a realm built around the presence of one irreplaceable ruler. While Trentrouls survives, its cities grow steadily more capable as history advances. Buddy, his beloved Golden Retriever, doubles both his battlefield confidence and the benefits he gives the empire. Una Court can win extraordinary tactical victories through Body Possession, but Trentrouls'' death ends the civilization immediately.'),
('TXT_KEY_CIV_UNA_COURT_STRATEGY', 'Keep Trentrouls alive and Buddy adjacent. Your empire-wide bonus grows with every Era, while Body Possession can steal the enemy''s most important unit for several turns. Do not expose Trentrouls carelessly: his death destroys Una Court.'),
('TXT_KEY_CIV5_UNA_COURT_HEADING_1', 'The Freehold'),
('TXT_KEY_CIV5_UNA_COURT_TEXT_1', 'Una Court is less a state than a promise: while its ruler stands, the Court endures. Every institution rests on that certainty, and every citizen understands the price of losing it.'),
('TXT_KEY_CIV5_UNA_COURT_HEADING_2', 'Trentrouls and Buddy'),
('TXT_KEY_CIV5_UNA_COURT_TEXT_2', 'Trentrouls is never alone in spirit. Buddy, a Golden Retriever of uncommon loyalty, brings out the ruler''s full strength and turns an already prosperous Court into a thriving one.'),
('TXT_KEY_CIV5_UNA_COURT_HEADING_3', 'Strategy'),
('TXT_KEY_CIV5_UNA_COURT_TEXT_3', 'Una Court rewards careful positioning and decisive action. Keep Buddy safe, allow the Era bonus to compound, and use Body Possession to break formations or consume exposed civilian units. A single reckless move can cost the entire campaign.'),
('TXT_KEY_CIV5_DOM_UNA_COURT_TEXT', 'The Court gathers around you, Trentrouls.[NEWLINE][NEWLINE]Its farms, workshops, treasuries, temples, and academies prosper because the people believe their ruler cannot be replaced. Beside you waits Buddy, loyal and fearless, ready to transform caution into strength.[NEWLINE][NEWLINE]The world will test that faith. Protect the life on which Una Court depends, seize the bodies of those who would oppose you, and create victories no ordinary ruler could imagine.'),

('TXT_KEY_CITY_NAME_UNA_COURT', 'Una Court'),
('TXT_KEY_CITY_NAME_UNA_BUDDY_PARK', 'Buddy Park'),
('TXT_KEY_CITY_NAME_UNA_FREEHOLD', 'The Freehold'),
('TXT_KEY_CITY_NAME_UNA_GOLDEN_FIELDS', 'Golden Fields'),
('TXT_KEY_CITY_NAME_UNA_CENTRELINK', 'Centrelink'),
('TXT_KEY_CITY_NAME_UNA_GREEN', 'Court Green'),
('TXT_KEY_CITY_NAME_UNA_RULERS_REST', 'Ruler''s Rest'),
('TXT_KEY_CITY_NAME_UNA_COMPANION_HILL', 'Companion Hill'),
('TXT_KEY_SPY_NAME_UNA_BUDDY', 'Buddy'),
('TXT_KEY_SPY_NAME_UNA_COURTIER', 'The Courtier'),
('TXT_KEY_SPY_NAME_UNA_KEEPER', 'The Keeper'),

('TXT_KEY_UNIT_UNA_TRENTROULS', 'Trentrouls'),
('TXT_KEY_UNIT_UNA_TRENTROULS_HELP', 'Irreplaceable Una Court hero. His strength increases every Era and doubles while Buddy is adjacent. May use Body Possession on an eligible enemy unit within 2 tiles. If Trentrouls dies, Una Court is eliminated.'),
('TXT_KEY_UNIT_UNA_TRENTROULS_STRATEGY', 'Keep Trentrouls behind the front line until Body Possession can decide the battle. Buddy doubles his strength, but concentrated ranged fire can still end your civilization immediately.'),
('TXT_KEY_UNIT_UNA_TRENTROULS_PEDIA', 'Trentrouls is not merely a unique unit. He is the continued existence of Una Court expressed on the map. He gains strength as the ages advance, keeps ordinary promotions, and can temporarily turn enemy bodies against their owners.'),

('TXT_KEY_UNIT_UNA_BUDDY', 'Buddy'),
('TXT_KEY_UNIT_UNA_BUDDY_HELP', 'Fragile Golden Retriever companion. Ignores terrain costs and never obsoletes. While adjacent to Trentrouls, doubles his Combat Strength and Una Court''s empire-wide Era bonus. Limited to one active copy.'),
('TXT_KEY_UNIT_UNA_BUDDY_STRATEGY', 'Keep Buddy next to Trentrouls but away from enemy attacks. Buddy is inexpensive compared with his strategic value, yet his low Combat Strength makes him easy to kill.'),
('TXT_KEY_UNIT_UNA_BUDDY_PEDIA', 'Buddy is Trentrouls'' closest companion and Una Court''s most obvious counterplay point. His presence doubles the ruler''s military strength and the prosperity he gives every city.'),

('TXT_KEY_BUILDING_UNA_CENTRELINK', 'Centrelink'),
('TXT_KEY_BUILDING_UNA_CENTRELINK_HELP', 'Replaces the Bank. Retains the Bank''s normal effects and provides +1 [ICON_HAPPINESS_1] Local Happiness.'),
('TXT_KEY_BUILDING_UNA_CENTRELINK_STRATEGY', 'Centrelink supports conquest and wider settlement after Banking without removing the need to manage Happiness.'),
('TXT_KEY_BUILDING_UNA_CENTRELINK_PEDIA', 'Centrelink is Una Court''s distinctive mid-game institution. Alongside the ordinary financial functions of a Bank, it provides a modest measure of local stability.'),

('TXT_KEY_PROMOTION_UNA_ONE_TRUE_RULER', 'The One True Ruler'),
('TXT_KEY_PROMOTION_UNA_ONE_TRUE_RULER_HELP', 'Irreplaceable. Cannot be captured and does not consume Supply. If this unit dies, Una Court collapses.'),
('TXT_KEY_PROMOTION_UNA_BELOVED_COMPANION', 'Beloved Companion'),
('TXT_KEY_PROMOTION_UNA_BELOVED_COMPANION_HELP', 'Ignores terrain costs and empowers adjacent Trentrouls.'),
('TXT_KEY_PROMOTION_UNA_BUDDY_IS_HERE', 'Buddy Is Here'),
('TXT_KEY_PROMOTION_UNA_BUDDY_IS_HERE_HELP', '+100% Combat Strength. Una Court''s city bonuses are also doubled.'),
('TXT_KEY_PROMOTION_UNA_POSSESSED', 'Possessed by Trentrouls'),
('TXT_KEY_PROMOTION_UNA_POSSESSED_HELP', 'Temporarily controlled by Una Court. It will return to its original owner when possession expires or peace is signed.'),
('TXT_KEY_PROMOTION_UNA_POSSESSION_READY', 'Body Possession: Ready'),
('TXT_KEY_PROMOTION_UNA_POSSESSION_READY_HELP', 'May possess one eligible enemy military or civilian unit within 2 tiles.'),
('TXT_KEY_PROMOTION_UNA_POSSESSION_COOLDOWN', 'Body Possession: Recharging'),
('TXT_KEY_PROMOTION_UNA_POSSESSION_COOLDOWN_HELP', 'Body Possession is currently on cooldown.'),
('TXT_KEY_PROMOTION_UNA_ERA_STRENGTH', 'Era Strength'),
('TXT_KEY_PROMOTION_UNA_ERA_STRENGTH_HELP', 'Trentrouls'' Combat Strength scales with Una Court''s current Era.'),

('TXT_KEY_BUILDING_UNA_COURT_BONUS', 'The Court Lives Through Him'),
('TXT_KEY_BUILDING_UNA_COURT_BONUS_HELP', 'Hidden building applying Una Court''s current Era-scaled city bonuses.'),
('TXT_KEY_BUILDING_UNA_COURT_BONUS_PEDIA', 'Internal Una Court scaling building.');
